-- Serviloop core schema (M1).
--
-- PART 1: tables, constraints, indexes, updated_at trigger.
-- PART 2 (bottom of this file): row level security, grants and policies.
-- Both parts ship in ONE migration so the tables never exist without protection.
--
-- Conventions
--   * UUID primary keys, generated by the database.
--   * Every business-owned row carries `business_id`.
--   * Text limits mirror the Zod rules in the app (src/features/customers/validation.ts).
--   * Timestamps are timestamptz (stored as UTC instants).

-- ---------------------------------------------------------------------------
-- businesses: one row per owner (v0.1 has a single owner login per business)
-- ---------------------------------------------------------------------------
create table public.businesses (
  id          uuid primary key default gen_random_uuid(),
  -- The owner is whoever is signed in when the row is created. The app never sends this value,
  -- and (see part 2) it can never be changed afterwards.
  owner_id    uuid not null unique default auth.uid() references auth.users (id) on delete cascade,
  name        text not null check (char_length(btrim(name)) between 2 and 100),
  created_at  timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- customers
-- ---------------------------------------------------------------------------
create table public.customers (
  id           uuid primary key default gen_random_uuid(),
  business_id  uuid not null references public.businesses (id) on delete cascade,
  name         text not null check (char_length(btrim(name)) between 2 and 100),
  phone        text check (phone is null or char_length(btrim(phone)) between 1 and 30),
  address      text check (address is null or char_length(btrim(address)) between 1 and 200),
  created_at   timestamptz not null default now(),
  -- Lets work_orders reference (customer, business) as a pair, so a job cannot point at a
  -- customer that belongs to a different business.
  unique (id, business_id)
);

-- ---------------------------------------------------------------------------
-- technicians (record only in v0.1: they do not sign in)
-- ---------------------------------------------------------------------------
create table public.technicians (
  id           uuid primary key default gen_random_uuid(),
  business_id  uuid not null references public.businesses (id) on delete cascade,
  name         text not null check (char_length(btrim(name)) between 2 and 100),
  specialty    text check (specialty is null or char_length(btrim(specialty)) between 1 and 100),
  -- Technicians who leave are deactivated, not deleted, so old jobs keep their history.
  active       boolean not null default true,
  created_at   timestamptz not null default now(),
  unique (id, business_id)
);

-- ---------------------------------------------------------------------------
-- work_orders (jobs)
-- ---------------------------------------------------------------------------
create table public.work_orders (
  id               uuid primary key default gen_random_uuid(),
  business_id      uuid not null references public.businesses (id) on delete cascade,
  customer_id      uuid not null,
  technician_id    uuid, -- optional: a job can exist before anyone is assigned
  title            text not null check (char_length(btrim(title)) between 2 and 120),
  description      text check (description is null or char_length(description) <= 2000),
  status           text not null default 'open'
                     check (status in ('open', 'in_progress', 'completed', 'cancelled')),
  scheduled_for    timestamptz,
  completion_notes text check (completion_notes is null or char_length(completion_notes) <= 4000),
  ai_summary       text check (ai_summary is null or char_length(ai_summary) <= 2000),
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),

  -- Tenant integrity enforced by the database itself: the customer (and technician) must belong
  -- to the SAME business as the job. Because business_id is part of the pair, a forged customer_id
  -- from another business has no matching row and is rejected.
  --
  -- ON DELETE NO ACTION: a customer or technician that still has jobs cannot be deleted. It is
  -- checked at the end of the statement, so deleting a whole business (which removes its customers
  -- and jobs together) still works.
  constraint work_orders_customer_same_business
    foreign key (customer_id, business_id)
    references public.customers (id, business_id)
    on delete no action,
  -- When technician_id is null this check is skipped (default MATCH SIMPLE), so the technician
  -- stays optional; when it is set, the pair must exist.
  constraint work_orders_technician_same_business
    foreign key (technician_id, business_id)
    references public.technicians (id, business_id)
    on delete no action
);

-- ---------------------------------------------------------------------------
-- Indexes: only those backing a real query.
--   customers/technicians (business_id)      list a business's customers / technicians
--   work_orders (business_id, status)        dashboard counts and status filters
--   work_orders (business_id, scheduled_for) jobs sorted by date
--   work_orders (customer_id)                a customer's jobs, and the "has jobs?" delete check
-- (businesses.owner_id is already indexed by its unique constraint.)
-- ---------------------------------------------------------------------------
create index customers_business_id_idx    on public.customers (business_id);
create index technicians_business_id_idx  on public.technicians (business_id);
create index work_orders_business_status_idx    on public.work_orders (business_id, status);
create index work_orders_business_scheduled_idx on public.work_orders (business_id, scheduled_for);
create index work_orders_customer_id_idx  on public.work_orders (customer_id);

-- ---------------------------------------------------------------------------
-- updated_at maintenance
-- ---------------------------------------------------------------------------
create function public.set_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

create trigger work_orders_set_updated_at
  before update on public.work_orders
  for each row execute function public.set_updated_at();

-- ===========================================================================
-- PART 2: ROW LEVEL SECURITY
--
-- In plain words:
--   * Anonymous (signed-out) visitors can do nothing with any table.
--   * A signed-in owner can only see and change rows belonging to THEIR business.
--   * A row can never be moved to another business, and a business's owner never changes:
--     those columns are simply not writable by the app.
--   * The database enforces this. The app's own filtering is a convenience, not the protection.
--
-- Method (Supabase guidance): enable RLS, REVOKE every default grant, then GRANT back only what the
-- app needs, and write one policy per operation, scoped `to authenticated`. Policies filter rows;
-- column-level grants decide which columns can be written.
-- ===========================================================================

alter table public.businesses  enable row level security;
alter table public.customers   enable row level security;
alter table public.technicians enable row level security;
alter table public.work_orders enable row level security;

-- Start from zero: Supabase hands out broad default privileges, and policies do not remove them.
revoke all on table public.businesses, public.customers, public.technicians, public.work_orders
  from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- businesses: an owner reads, creates and renames their own business. Never deletes via the API.
-- Insert is limited to the `name` column, so the app cannot choose `id` or `owner_id`
-- (owner_id is filled in by the database from the signed-in user).
-- ---------------------------------------------------------------------------
grant select on public.businesses to authenticated;
grant insert (name) on public.businesses to authenticated;
grant update (name) on public.businesses to authenticated;

create policy "owner can read own business"
  on public.businesses for select to authenticated
  using (owner_id = (select auth.uid()));

create policy "owner can create own business"
  on public.businesses for insert to authenticated
  with check (owner_id = (select auth.uid()));

create policy "owner can rename own business"
  on public.businesses for update to authenticated
  using (owner_id = (select auth.uid()))
  with check (owner_id = (select auth.uid()));

-- ---------------------------------------------------------------------------
-- customers: full control of own customers. `business_id` is writable on insert only.
-- (A customer that still has jobs cannot be deleted: see the foreign key above.)
-- ---------------------------------------------------------------------------
grant select, delete on public.customers to authenticated;
grant insert (business_id, name, phone, address) on public.customers to authenticated;
grant update (name, phone, address) on public.customers to authenticated;

create policy "owner can read own customers"
  on public.customers for select to authenticated
  using (business_id in (select id from public.businesses where owner_id = (select auth.uid())));

create policy "owner can add customers to own business"
  on public.customers for insert to authenticated
  with check (business_id in (select id from public.businesses where owner_id = (select auth.uid())));

create policy "owner can edit own customers"
  on public.customers for update to authenticated
  using (business_id in (select id from public.businesses where owner_id = (select auth.uid())))
  with check (business_id in (select id from public.businesses where owner_id = (select auth.uid())));

create policy "owner can delete own customers"
  on public.customers for delete to authenticated
  using (business_id in (select id from public.businesses where owner_id = (select auth.uid())));

-- ---------------------------------------------------------------------------
-- technicians: read, add, edit (including deactivate). No delete: deactivate instead.
-- ---------------------------------------------------------------------------
grant select on public.technicians to authenticated;
grant insert (business_id, name, specialty, active) on public.technicians to authenticated;
grant update (name, specialty, active) on public.technicians to authenticated;

create policy "owner can read own technicians"
  on public.technicians for select to authenticated
  using (business_id in (select id from public.businesses where owner_id = (select auth.uid())));

create policy "owner can add technicians to own business"
  on public.technicians for insert to authenticated
  with check (business_id in (select id from public.businesses where owner_id = (select auth.uid())));

create policy "owner can edit own technicians"
  on public.technicians for update to authenticated
  using (business_id in (select id from public.businesses where owner_id = (select auth.uid())))
  with check (business_id in (select id from public.businesses where owner_id = (select auth.uid())));

-- ---------------------------------------------------------------------------
-- work_orders: full control of own jobs. `updated_at`, `created_at`, `id` are never app-writable.
-- Which customer/technician a job may point at is enforced by the composite foreign keys, so even
-- with a forged id the row must belong to the same business.
-- ---------------------------------------------------------------------------
grant select, delete on public.work_orders to authenticated;
grant insert (business_id, customer_id, technician_id, title, description, status,
              scheduled_for, completion_notes, ai_summary)
  on public.work_orders to authenticated;
grant update (customer_id, technician_id, title, description, status,
              scheduled_for, completion_notes, ai_summary)
  on public.work_orders to authenticated;

create policy "owner can read own jobs"
  on public.work_orders for select to authenticated
  using (business_id in (select id from public.businesses where owner_id = (select auth.uid())));

create policy "owner can create jobs in own business"
  on public.work_orders for insert to authenticated
  with check (business_id in (select id from public.businesses where owner_id = (select auth.uid())));

create policy "owner can edit own jobs"
  on public.work_orders for update to authenticated
  using (business_id in (select id from public.businesses where owner_id = (select auth.uid())))
  with check (business_id in (select id from public.businesses where owner_id = (select auth.uid())));

create policy "owner can delete own jobs"
  on public.work_orders for delete to authenticated
  using (business_id in (select id from public.businesses where owner_id = (select auth.uid())));

-- The trigger function is internal plumbing: nobody should be able to call it through the API.
-- (Triggers keep working; only direct EXECUTE is removed.)
revoke execute on function public.set_updated_at() from public, anon, authenticated;
